import { createExpandedSeed } from '@/data/seed/expanded-seed';
import { DEMO_IDS } from '@/data/seed';
import type { DomainState } from '@/domain/entities';
import { executeDesign,type DesignCommand } from '@/services/transactions/designs';
import { executeProduction,type ProductionCommand } from '@/services/transactions/production';
import { materialCatalog } from '@/services/designs/planning';
import { executeProcessing,type ProcessingCommand } from '@/services/transactions/processing';
export const productionDate='2026-10-15',productionContext={actorId:DEMO_IDS.actor,at:'2026-10-15T14:00:00.000Z',role:'owner' as const};
export function productionAct(d:DomainState,c:ProductionCommand){const r=executeProduction(d,c,productionContext);if(!r.ok)throw new Error(c.kind+': '+r.error.message);return r.state;}
const designCache=new Map<number,DomainState>();
export function productionFixture(pieces:2|3=3){const saved=designCache.get(pieces);if(saved){const d=structuredClone(saved),source=materialCatalog(d).filter(r=>r.eligible).sort((a,b)=>b.availableMeters-a.availableMeters)[0];return{d,source,collectionId:Object.keys(d.studio!.collections)[0],designId:Object.keys(d.studio!.designs)[0],variantId:Object.keys(d.studio!.variants)[0],bomId:Object.keys(d.studio!.boms)[0]};}let d=createExpandedSeed();const source=materialCatalog(d).filter(r=>r.eligible).sort((a,b)=>b.availableMeters-a.availableMeters)[0];const design=(c:DesignCommand)=>{const r=executeDesign(d,c,productionContext);if(!r.ok)throw new Error(c.kind+': '+r.error.message);d=r.state;};
 design({kind:'saveCollection',code:'PROD-TEST',name:'پیداواری کلیکشن',nameEnglish:'Production',season:'SUMMER',year:2026,description:'',launchOn:productionDate,status:'ACTIVE',notes:''});const collectionId=Object.keys(d.studio!.collections)[0];design({kind:'saveDesign',name:'پیداواری ڈیزائن',nameEnglish:'',collectionId,season:'SUMMER',pieceCount:pieces,fabricCategory:'لان',description:'',designerId:DEMO_IDS.actor,date:productionDate,targetSuits:200,targetPricePaisa:200000,notes:''});const designId=Object.keys(d.studio!.designs)[0];design({kind:'saveVariant',designId,code:'PLAIN',name:'سادہ',nameEnglish:'',colorCode:'PLAIN',colorHex:'#eeeeee',shade:'',materialLotIds:[],notes:''});const variantId=Object.keys(d.studio!.variants)[0];design({kind:'variantAction',id:variantId,action:'APPROVE'});design({kind:'saveBOM',designId,variantId,effectiveOn:productionDate,reason:'پیداواری مواد',lines:Array.from({length:pieces},(_,i)=>({key:'line-'+i,component:i===0?'SHIRT':i===1?'TROUSER':'DUPATTA',materialType:'FABRIC',fabricId:source.fabricId,lotId:source.lotId,colorPolicy:'ANY',quantity:i===0?2.7:1,unit:'METER',wastePercent:10,ratePaisa:10000,costSource:'MANUAL',availabilityUntracked:false,notes:''}))});const bomId=Object.keys(d.studio!.boms)[0];design({kind:'bomAction',id:bomId,action:'SUBMIT'});design({kind:'bomAction',id:bomId,action:'APPROVE'});design({kind:'saveSample',designId,variantId,bomId,type:'پروٹوٹائپ',date:productionDate,targetOn:productionDate,notes:'',materialNotes:'',previewName:'',previewData:''});const sample=Object.values(d.studio!.samples)[0];design({kind:'sampleAction',id:sample.id,action:'SUBMIT'});design({kind:'reviewSample',id:sample.id,result:'PASS',checklist:{color:'PASS',print:'PASS',fabric:'PASS',matching:'PASS',embroidery:'PASS',completeness:'PASS',market:'PASS',feasibility:'PASS'},comments:''});design({kind:'designAction',id:designId,action:'APPROVE',notes:''});designCache.set(pieces,structuredClone(d));return{d,source,collectionId,designId,variantId,bomId};}
export function orderFixture(pieces:2|3=3){const f=productionFixture(pieces);let d=productionAct(f.d,{kind:'savePlan',collectionId:f.collectionId,designId:f.designId,variantId:f.variantId,bomId:f.bomId,date:productionDate,targetSuits:200,startOn:productionDate,finishOn:'2026-10-25',priority:'NORMAL',managerId:DEMO_IDS.actor,remarks:''});const planId=Object.keys(d.production!.plans)[0];for(const action of ['SUBMIT','APPROVE']as const)d=productionAct(d,{kind:'planAction',id:planId,action,reason:''});d=productionAct(d,{kind:'saveOrder',planId,date:productionDate,startOn:productionDate,finishOn:'2026-10-25',managerId:DEMO_IDS.actor,remarks:'',untrackedAcknowledged:false});const orderId=Object.keys(d.production!.orders)[0];d=productionAct(d,{kind:'orderAction',id:orderId,action:'APPROVE',reason:''});return{...f,d,planId,orderId};}
export function issueFixture(f:ReturnType<typeof orderFixture>,line='line-0',quantity=300){let d=productionAct(f.d,{kind:'reserveMaterial',orderId:f.orderId,bomLineKey:line,lotId:f.source.lotId,locationId:f.source.locationId,quantityMeters:quantity,date:productionDate,reason:'پیداواری ضرورت'});const reservation=Object.values(d.warehouse!.reservationProfiles).at(-1)!;d=productionAct(d,{kind:'createMaterialIssue',orderId:f.orderId,reservationProfileId:reservation.id,date:productionDate,quantityMeters:quantity,receiverId:DEMO_IDS.actor,section:'کٹنگ',remarks:''});const issueId=Object.keys(d.production!.issues).at(-1)!;d=productionAct(d,{kind:'issueAction',id:issueId,action:'POST'});return{...f,d,issueId,reservationId:reservation.id};}
export function cutFixture(){const f=issueFixture(orderFixture());let d=productionAct(f.d,{kind:'saveCutting',orderId:f.orderId,issueId:f.issueId,date:productionDate,inputMeters:300,usableMeters:270,leftoverMeters:20,scrapMeters:5,remainingMeters:5,outputQuantity:100,unit:'PANEL',method:'دستی',operatorId:DEMO_IDS.actor,startOn:productionDate,finishOn:productionDate,reason:'کٹنگ نقص'});const cuttingId=Object.keys(d.production!.cuttings)[0];d=productionAct(d,{kind:'cuttingAction',id:cuttingId,action:'POST'});return{...f,d,cuttingId,componentId:Object.keys(d.production!.componentLots)[0]};}
export function embroideryFixture(twoBatches=false){const f=cutFixture();let d=f.d;const componentIds=[f.componentId];if(twoBatches){const more=issueFixture({...f,d},'line-0',270);d=productionAct(more.d,{kind:'saveCutting',orderId:f.orderId,issueId:more.issueId,date:productionDate,inputMeters:270,usableMeters:270,leftoverMeters:0,scrapMeters:0,remainingMeters:0,outputQuantity:100,unit:'PANEL',method:'دستی',operatorId:DEMO_IDS.actor,startOn:productionDate,finishOn:productionDate,reason:''});const cut=Object.keys(d.production!.cuttings).at(-1)!;d=productionAct(d,{kind:'cuttingAction',id:cut,action:'POST'});componentIds.push(Object.keys(d.production!.componentLots).at(-1)!);}const command:ProcessingCommand={kind:'saveContractor',name:'ٹیسٹ کڑھائی کمپنی',nameEnglish:'Embroidery',code:'EMB-TEST',contact:'منیجر',phone:'03001234567',city:'لاہور',address:'مارکیٹ',services:['EMBROIDERY'],termDays:30,notes:'',status:'ACTIVE'};const r=executeProcessing(d,command,productionContext);if(!r.ok)throw new Error(r.error.message);d=r.state;const contractorId=Object.keys(d.contractors).at(-1)!;d=productionAct(d,{kind:'createEmbroidery',orderId:f.orderId,contractorId,date:productionDate,service:'پینل کڑھائی',pattern:'NT-PATTERN',expectedOn:productionDate,lines:componentIds.map(componentLotId=>({componentLotId,quantity:100,fromState:'QC_PENDING'})),unit:'PANEL',rateUnit:'PANEL',ratePaisa:8500,serviceQuantity:componentIds.length*100,rateBasis:'',additionalPaisa:0,discountPaisa:0});const jobId=Object.keys(d.production!.embroidery)[0];d=productionAct(d,{kind:'embroideryAction',id:jobId,action:'POST'});return{...f,d,componentIds,contractorId,jobId};}
